<?php require_once __DIR__."/api/auth_common.php"; requireAdmin(false); ?>
<!doctype html><html lang="es"><head><link rel="icon" type="image/svg+xml" href="https://static.jocarsa.com/logos/crimson.svg"><meta charset="utf-8"><title>Configuración · Crimson</title>
<link rel="stylesheet" href="nucleo/estilo/general.css?v=031"><style>
body{display:block;background:#f6f7f8}.top{height:60px;background:crimson;color:white;display:flex;align-items:center;padding:10px 14px;gap:12px}.top strong{font-size:16px}.top .spacer{flex:1}.top a{background:white;color:crimson;padding:9px 12px;text-decoration:none;border-radius:3px}.cfg{height:calc(100vh - 60px);display:grid;grid-template-columns:260px 1fr}.mods{background:crimson;padding:10px;overflow:auto}.mods button{width:100%;display:block;text-align:left;background:white;color:crimson;border:1px solid #ddd;padding:10px;margin-bottom:7px;cursor:pointer}.mods button.active{background:#a80f2d;color:white;border-color:white}.maincfg{padding:20px;overflow:auto}.card{background:white;border:1px solid #ddd;padding:18px;max-width:1050px}.create{display:flex;gap:8px;margin-bottom:16px}.create input{padding:9px;border:1px solid #ccc;min-width:260px}.create button,.actions button{padding:9px 13px;border:0;background:crimson;color:white;cursor:pointer}.tables{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:6px;margin:14px 0}.tables label{display:flex;align-items:center;gap:7px;padding:8px;background:#fafafa;border:1px solid #e4e4e4}.actions{display:flex;gap:8px}.actions .danger{background:#555}.muted{color:#777}.empty{padding:30px;color:#777;text-align:center}
</style></head><body>
<header class="top"><strong>jocarsa | crimson · configuración</strong><span>Administración de módulos y estructura</span><span class="spacer"></span><a href="index.html">Volver al ERP</a></header>
<div class="cfg"><aside class="mods"><button id="tabModules" class="active" style="width:100%;padding:12px;margin-bottom:8px">Aplicaciones</button><button id="tabData" style="width:100%;padding:12px;margin-bottom:14px">Estructura de datos</button><div id="moduleList"></div><div id="tableList" style="display:none"></div></aside><main class="maincfg">
<div class="card" id="modulePanel"><h1>Módulos</h1><div class="create"><input id="newName" placeholder="Nombre del nuevo módulo"><button id="createBtn">Crear módulo</button></div>
<div id="editor" class="empty">Selecciona un módulo de la izquierda.</div></div><div class="card" id="dataPanel" style="display:none"><h1>Estructura de datos</h1><p class="muted">Edición de entidades y relaciones sobre JocarsaBBDD. Las operaciones destructivas requieren confirmación.</p><div class="create"><input id="newTable" placeholder="Nombre de nueva tabla"><button id="addTable">Crear tabla</button></div><div id="structureEditor" class="empty">Selecciona una tabla de la izquierda.</div><div class="actions"><button id="previewMigration">Vista previa de migración</button><button id="applyMigration">Aplicar migración</button></div><pre id="migrationPreview" style="white-space:pre-wrap;overflow:auto;background:#f5f5f5;padding:12px"></pre></div></main></div>
<script>
let data=null,current=null;
async function api(action,body=null){const r=await fetch("api/configuracion.php?action="+action,{method:body?"POST":"GET",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):null,cache:"no-store"});const d=await r.json();if(!d.ok)throw new Error(d.error);return d}
async function load(select=null){data=await api("list");renderModules();if(select)selectModule(select);else if(current&&data.modules.some(m=>m.modulo===current))selectModule(current)}
function renderModules(){moduleList.innerHTML="";data.modules.forEach(m=>{const b=document.createElement("button");b.textContent=m.nombre;b.dataset.id=m.modulo;b.onclick=()=>selectModule(m.modulo);moduleList.appendChild(b)})}
function selectModule(id){current=id;document.querySelectorAll("#moduleList button").forEach(b=>b.classList.toggle("active",b.dataset.id===id));const m=data.modules.find(x=>x.modulo===id);if(!m)return;
 editor.className="";editor.innerHTML=`<h2>${m.nombre}</h2><p class="muted">Carpeta: <code>modulos/${m.modulo}/</code> · marca las tablas de JocarsaBBDD que debe mostrar este módulo.</p><div class="tables" id="checks"></div><div class="actions"><button id="saveBtn">Guardar tablas</button><button class="danger" id="deleteBtn">Eliminar módulo</button></div>`;
 data.tables.forEach(t=>{const l=document.createElement("label");const c=document.createElement("input");c.type="checkbox";c.value=t;c.checked=m.tablas.includes(t);l.append(c,document.createTextNode(t));checks.appendChild(l)});
 saveBtn.onclick=async()=>{const tablas=[...checks.querySelectorAll("input:checked")].map(x=>x.value);try{await api("save",{modulo:m.modulo,tablas});await load(m.modulo);alert("Módulo actualizado")}catch(e){alert(e.message)}};
 deleteBtn.onclick=async()=>{if(!confirm(`¿Eliminar el módulo "${m.nombre}"? No se elimina ninguna tabla de JocarsaBBDD.`))return;try{await api("delete",{modulo:m.modulo});current=null;editor.className="empty";editor.textContent="Selecciona un módulo de la izquierda.";await load()}catch(e){alert(e.message)}};
}
createBtn.onclick=async()=>{const nombre=newName.value.trim();if(!nombre)return;try{const d=await api("create",{nombre});newName.value="";await load(d.modulo)}catch(e){alert(e.message)}};
load().catch(e=>{editor.className="empty";editor.textContent="Error cargando módulos: "+e.message;console.error(e);});

let structure=null,selectedTable=null;
const safeName=n=>/^[A-Za-z_][A-Za-z0-9_]*$/.test(n)&&!n.startsWith('__crimson_');
const htmlEscape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function modelApi(action,model=null){const r=await fetch('api/modelo.php?action='+action,{method:model?'POST':'GET',headers:model?{'Content-Type':'application/json'}:{},body:model?JSON.stringify({model}):null,cache:'no-store'});const d=await r.json();if(!d.ok)throw Error(d.error);return d;}
async function loadStructure(){const d=await modelApi('get');structure=d.actual;structure.tables=structure.tables.filter(t=>!t.name.startsWith('__crimson_'));structure.relations=structure.relations.filter(r=>!r.fromTable.startsWith('__crimson_')&&!r.toTable.startsWith('__crimson_'));renderTableList();if(selectedTable)editTable(selectedTable);}
function renderTableList(){tableList.innerHTML='';structure.tables.forEach(t=>{const b=document.createElement('button');b.textContent=t.name;b.className=t.name===selectedTable?'active':'';b.onclick=()=>editTable(t.name);tableList.append(b)});}
function editTable(name){selectedTable=name;renderTableList();const t=structure.tables.find(t=>t.name===name);if(!t){structureEditor.textContent='Selecciona una tabla';return;}structureEditor.className='';structureEditor.innerHTML='<h2>'+htmlEscape(name)+'</h2><p>Campos y tipos</p><div id="fieldRows"></div><div class="create"><input id="fieldName" placeholder="Nombre del campo"><select id="fieldType"><option>TEXT</option><option>INTEGER</option><option>REAL</option><option>NUMERIC</option><option>BOOLEAN</option><option>DATE</option></select><button id="addField">Añadir campo</button></div><h3>Claves foráneas</h3><div id="fkRows"></div><div class="create"><select id="fkFrom"></select><select id="fkToTable"></select><select id="fkToCol"></select><button id="addFk">Añadir FK</button></div><button id="dropTable" style="background:#555;color:white;padding:10px">Eliminar tabla</button>';
 const renderFields=()=>{fieldRows.innerHTML='';t.columns.forEach(c=>{const line=document.createElement('div');line.style='padding:8px;border-bottom:1px solid #ddd;display:flex;gap:12px;align-items:center';const label=document.createElement('span');label.textContent=c.name+' · '+c.type;label.style.flex='1';line.append(label);if(c.name!=='Identificador'){const b=document.createElement('button');b.textContent='Eliminar';b.onclick=()=>{if(!confirm('Eliminar campo '+c.name+' y sus datos al aplicar la migración?'))return;t.columns=t.columns.filter(x=>x!==c);structure.relations=structure.relations.filter(r=>!(r.fromTable===name&&r.fromColumn===c.name)&&!(r.toTable===name&&r.toColumn===c.name));editTable(name)};line.append(b)}fieldRows.append(line)});};renderFields();
 addField.onclick=()=>{const n=fieldName.value.trim();if(!safeName(n)||t.columns.some(c=>c.name===n)){alert('Nombre inválido o duplicado');return;}t.columns.push({name:n,type:fieldType.value,pk:false});editTable(name)};
 const renderFk=()=>{fkRows.innerHTML='';structure.relations.filter(r=>r.fromTable===name).forEach(r=>{const line=document.createElement('div');line.style='padding:8px';line.textContent=r.fromColumn+' → '+r.toTable+'.'+r.toColumn+' ';const b=document.createElement('button');b.textContent='Quitar del modelo';b.onclick=()=>{alert('La eliminación de FK existentes no está soportada por el conector; no se aplicará.');};line.append(b);fkRows.append(line)});};renderFk();
 t.columns.filter(c=>c.name!=='Identificador').forEach(c=>fkFrom.add(new Option(c.name,c.name)));structure.tables.forEach(x=>fkToTable.add(new Option(x.name,x.name)));
 const fillDest=()=>{fkToCol.innerHTML='';const dest=structure.tables.find(x=>x.name===fkToTable.value);(dest?.columns||[]).forEach(c=>fkToCol.add(new Option(c.name,c.name)));fkToCol.value='Identificador'};fkToTable.onchange=fillDest;fillDest();
 addFk.onclick=()=>{if(!fkFrom.value||!fkToTable.value||!fkToCol.value)return;const old=structure.relations.find(r=>r.fromTable===name&&r.fromColumn===fkFrom.value);if(old){alert('Ya existe una FK en este campo');return;}structure.relations.push({fromTable:name,fromColumn:fkFrom.value,toTable:fkToTable.value,toColumn:fkToCol.value});editTable(name)};
 dropTable.onclick=()=>{if(!confirm('Eliminar tabla '+name+' y todos sus datos al aplicar?'))return;structure.tables=structure.tables.filter(x=>x!==t);structure.relations=structure.relations.filter(r=>r.fromTable!==name&&r.toTable!==name);selectedTable=null;renderTableList();structureEditor.textContent='Tabla pendiente de eliminación';};
}
tabModules.onclick=()=>{modulePanel.style.display='';dataPanel.style.display='none';moduleList.style.display='';tableList.style.display='none';tabModules.className='active';tabData.className=''};
tabData.onclick=async()=>{modulePanel.style.display='none';dataPanel.style.display='';moduleList.style.display='none';tableList.style.display='';tabModules.className='';tabData.className='active';try{await loadStructure()}catch(e){structureEditor.textContent=e.message}};
addTable.onclick=()=>{const n=newTable.value.trim();if(!safeName(n)||structure.tables.some(t=>t.name===n)){alert('Nombre inválido o duplicado');return;}structure.tables.push({name:n,x:40,y:40,columns:[{name:'Identificador',type:'INTEGER',pk:true}]});newTable.value='';editTable(n)};
previewMigration.onclick=async()=>{try{migrationPreview.textContent=(await modelApi('preview',structure)).sql}catch(e){migrationPreview.textContent=e.message}};
applyMigration.onclick=async()=>{try{const preview=(await modelApi('preview',structure)).sql;migrationPreview.textContent=preview;if(!confirm('Aplicar los cambios al esquema real? Revisa antes los posibles borrados de datos.'))return;const d=await modelApi('apply',structure);alert('Migración aplicada: '+d.migration);await loadStructure();await load()}catch(e){alert('No se aplicó la migración: '+e.message)}};
</script></body></html>
